// RosterSpec snapshot
export interface RosterSpec_Snap { readonly title: string; readonly seats: readonly RosterSpecSeat_Snap[]; }
export const readRosterSpec = (m: Mem, p: number): RosterSpec_Snap => {
    const n_title = m.dv.getUint16(p + 4, true);
    if (!(n_title >= 0 && n_title <= 400)) throw new RangeError(`RosterSpec.title: count ${n_title} is outside 0..400`);
    const n_seats = m.dv.getInt32(p, true);
    if (!(n_seats >= 0 && n_seats <= 8)) throw new RangeError(`RosterSpec.seats: count ${n_seats} is outside 0..8`);
    const seats: RosterSpecSeat_Snap[] = new Array(n_seats);
    for (let i = 0; i < n_seats; i++) seats[i] = readRosterSpecSeat(m, p + 406 + i * 380);
    return { title: utf8Get(m, p + 6, n_title), seats: seats };
};
// RosterTrailerRead snapshot
export interface RosterTrailerRead_Snap { readonly status: number; readonly aiMask: number; readonly consumed: number; readonly gid: string; }
export const readRosterTrailerRead = (m: Mem, p: number): RosterTrailerRead_Snap => {
    const n_gid = m.dv.getUint16(p + 12, true);
    if (!(n_gid >= 0 && n_gid <= 64)) throw new RangeError(`RosterTrailerRead.gid: count ${n_gid} is outside 0..64`);
    return { status: m.dv.getInt32(p, true), aiMask: m.dv.getUint32(p + 4, true), consumed: m.dv.getInt32(p + 8, true), gid: utf8Get(m, p + 14, n_gid) };
};
// RosterSpecSeat snapshot
export interface RosterSpecSeat_Snap { readonly id: string; readonly name: string; readonly brain: string; }
export const readRosterSpecSeat = (m: Mem, p: number): RosterSpecSeat_Snap => {
    const n_id = m.dv.getUint16(p, true);
    if (!(n_id >= 0 && n_id <= 72)) throw new RangeError(`RosterSpecSeat.id: count ${n_id} is outside 0..72`);
    const n_name = m.dv.getUint16(p + 74, true);
    if (!(n_name >= 0 && n_name <= 256)) throw new RangeError(`RosterSpecSeat.name: count ${n_name} is outside 0..256`);
    const n_brain = m.dv.getUint16(p + 332, true);
    if (!(n_brain >= 0 && n_brain <= 46)) throw new RangeError(`RosterSpecSeat.brain: count ${n_brain} is outside 0..46`);
    return { id: utf8Get(m, p + 2, n_id), name: utf8Get(m, p + 76, n_name), brain: utf8Get(m, p + 334, n_brain) };
};
export const writeRosterSpec = (m: Mem, p: number, s: RosterSpec_Snap): void => {
    m.dv.setUint16(p + 4, utf8Set(m, p + 6, 400, s.title, 'RosterSpec.title'), true);
    const n_seats = s.seats.length;
    if (n_seats > 8) throw new RangeError(`RosterSpec.seats: ${n_seats} elements do not fit in 8`);
    m.dv.setInt32(p, n_seats, true);
    for (let i = 0; i < n_seats; i++) writeRosterSpecSeat(m, p + 406 + i * 380, s.seats[i]);
};
export const writeRosterSpecSeat = (m: Mem, p: number, s: RosterSpecSeat_Snap): void => {
    m.dv.setUint16(p, utf8Set(m, p + 2, 72, s.id, 'RosterSpecSeat.id'), true);
    m.dv.setUint16(p + 74, utf8Set(m, p + 76, 256, s.name, 'RosterSpecSeat.name'), true);
    m.dv.setUint16(p + 332, utf8Set(m, p + 334, 46, s.brain, 'RosterSpecSeat.brain'), true);
};
